// Enhanced UTC date parser
function parseDate(input) {
  if (!input) return new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate())).toISOString().split('T')[0]; // Default to today UTC if empty

  const now = new Date();
  const today = new Date(Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate()
  ));
  const lowerInput = input.toLowerCase().trim();

  if (lowerInput === 'today') return today.toISOString().split('T')[0];

  if (lowerInput === 'tomorrow') {
    const tomorrow = new Date(today);
    tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
    return tomorrow.toISOString().split('T')[0];
  }

  const nextDayMatch = lowerInput.match(/next (\w+)/);
  if (nextDayMatch) {
    const targetDay = nextDayMatch[1].substring(0, 3);
    const days = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
    const targetIndex = days.indexOf(targetDay);
    if (targetIndex !== -1) {
      const currentDay = today.getUTCDay();
      let diff = targetIndex - currentDay;
      if (diff <= 0) diff += 7;
      const nextDate = new Date(today);
      nextDate.setUTCDate(today.getUTCDate() + diff);
      return nextDate.toISOString().split('T')[0];
    }
  }

  const daysLaterMatch = lowerInput.match(/in (\d+) days?/);
  if (daysLaterMatch) {
    const days = parseInt(daysLaterMatch[1], 10);
    const futureDate = new Date(today);
    futureDate.setUTCDate(today.getUTCDate() + days);
    return futureDate.toISOString().split('T')[0];
  }

  try {
    const parsedDate = new Date(input);
    if (!isNaN(parsedDate)) {
      // Ensure it's interpreted as UTC if no timezone info present
      const offset = parsedDate.getTimezoneOffset() * 60000;
      const utcDate = new Date(parsedDate.getTime() + offset);
      if (input.length === 10 && input.includes('-')) { // Likely YYYY-MM-DD, assume UTC
         return new Date(Date.UTC(parsedDate.getFullYear(), parsedDate.getMonth(), parsedDate.getDate())).toISOString().split('T')[0];
      }
      return utcDate.toISOString().split('T')[0];
    }
  } catch (e) {}

  return input; // Return original input if parsing fails
}

