  };
}
console.log(`[Format Slot Times] Extracted slots array (length ${slots.length}):`, JSON.stringify(slots));

let filteredSlots = slots;
let filterMessage = '';
if (timePreference) {
  console.log(`[Format Slot Times] Filtering slots for: ${timePreference}`);
  if (timePreference === 'morning') {
    filteredSlots = slots.filter(slot => {
      const hour = parseInt((slot.start_time || '').split(':')[0], 10);
      return !isNaN(hour) && hour < 12;
    });
    filterMessage = ' morning';
  } else if (timePreference === 'afternoon') {
    filteredSlots = slots.filter(slot => {
      const hour = parseInt((slot.start_time || '').split(':')[0], 10);
      return !isNaN(hour) && hour >= 12 && hour < 17;
    });
    filterMessage = ' afternoon';
  } else if (timePreference === 'evening') {
    filteredSlots = slots.filter(slot => {
      const hour = parseInt((slot.start_time || '').split(':')[0], 10);
      return !isNaN(hour) && hour >= 17;
    });
    filterMessage = ' evening';
  }
  console.log(`[Format Slot Times] Filtered slots count: ${filteredSlots.length}`);
}

if (filteredSlots.length === 0) {
  let noSlotsMessage = `Sorry, no available${filterMessage} slots were found for Dr. ID ${inputData.doctorId} on ${appointmentDate} ${serviceInfo}.`;
  if (filterMessage && slots.length > 0) {
      noSlotsMessage += ` Would you like to check other times on this day or a different date?`;
  } else if (!filterMessage && slots.length === 0) {
       noSlotsMessage += ` Please try another date or check available doctors again.`;
  }
  console.log("[Format Slot Times] No slots after filtering/initial check.");
  return {
    results: [{ toolCallId, result: noSlotsMessage }]
  };
}

const timeCategories = {
  morning: { start: 0, end: 12, slots: [] },
  afternoon: { start: 12, end: 17, slots: [] },
  evening: { start: 17, end: 24, slots: [] }
};

filteredSlots.forEach(slot => {
  const startTime = slot.start_time || slot.startTime || slot.start;
  if (!startTime) return;
  const [hourStr] = startTime.split(':');
  const hour = parseInt(hourStr, 10);
  if (isNaN(hour)) return;

  if (hour < timeCategories.morning.end) timeCategories.morning.slots.push(startTime);
  else if (hour < timeCategories.afternoon.end) timeCategories.afternoon.slots.push(startTime);
  else timeCategories.evening.slots.push(startTime);
});

const formatCategory = (category, icon, categoryName) => {
  if (timePreference && timePreference !== categoryName && category.slots.length > 0 && filteredSlots.length > 0) return ''; 
  if (category.slots.length === 0) return '';

  const formatted = category.slots.slice(0, 5).map(time => `⏰ ${time}`).join('\n');
  let output = `${icon} ${category.slots.length} slots available:\n${formatted}`;
  if (category.slots.length > 5) {
    output += `\n... and ${category.slots.length - 5} more`;
  }
  return output + '\n\n';
};

