resultText += formatCategory(timeCategories.morning, '🌅 Morning', 'morning');
resultText += formatCategory(timeCategories.afternoon, '☀️ Afternoon', 'afternoon');
resultText += formatCategory(timeCategories.evening, '🌙 Evening', 'evening');

